import React, { forwardRef } from 'react';
import { FormattedMessage } from 'react-intl';
import styled from 'styled-components';

import Colors from '@dynatrace/strato-design-tokens/colors';
import Spacings from '@dynatrace/strato-design-tokens/spacings';

import type { WithChildren } from '../../core/types/with-children.js';
import { Flex } from '../../layouts-core/flex/Flex.js';
import { Text } from '../../typography/Text.js';

//#region Typings
export type EmptyStateProps = WithChildren;
//#endregion Typings

// #region StyledComponents
const StyledText = /* @__PURE__ */ styled(Text)({
  padding: `${Spacings.Size8} 0`,
  color: Colors.Text.Neutral.Subdued,
});
//// #endregion

// A helper component is utilized to encapsulate an empty state message and centrally align it.
const EmptyStateTextWrapper = /* @__PURE__ */ forwardRef<
  HTMLDivElement,
  EmptyStateProps
>(({ children }, forwardedRef) => {
  return (
    <Flex
      justifyContent="center"
      ref={forwardedRef}
      alignItems="center"
      height="100%"
      paddingLeft={12}
      paddingRight={12}
    >
      {children}
    </Flex>
  );
});

/**
 * EmptyState component used to indicate the empty state to the end user
 */
export const EmptyState = /* @__PURE__ */ forwardRef<
  HTMLDivElement,
  EmptyStateProps
>(({ children }, forwardedRef) => {
  if (children) {
    return typeof children === 'string' ? (
      <EmptyStateTextWrapper ref={forwardedRef}>
        <StyledText data-testid="text" textStyle="base">
          {children}
        </StyledText>
      </EmptyStateTextWrapper>
    ) : (
      // eslint-disable-next-line react/jsx-no-useless-fragment
      <>{children}</>
    );
  }
  return (
    <EmptyStateTextWrapper ref={forwardedRef}>
      <StyledText data-testid="text" textStyle="base">
        <FormattedMessage
          defaultMessage="No data available"
          id="jXX6iT3YZr7nUfi5"
          description="Message to display when no data is available"
        />
      </StyledText>
    </EmptyStateTextWrapper>
  );
});

(EmptyState as typeof EmptyState & { displayName: string }).displayName =
  'EmptyState';
